# The clock is fixed at 20 March, so the window is the nights of 13..19 March.
def test_T_116_7_page_shows_summary_above_the_diary(client):
    for day in (16, 17, 18):
        client.post(
            "/nights",
            data={
                "bedtime": f"2026-03-{day}T23:00",
                "wake_time": f"2026-03-{day + 1}T07:00",
                "timezone": "America/Toronto",
            },
        )
    page = client.get("/").text
    assert 'data-testid="weekly-summary"' in page
    assert page.index('data-testid="weekly-summary"') < page.index('data-testid="diary-table"')
    assert "8 h 0 min" in page
    assert "23:00" in page


